import{_ as a,o as t,c as r,ah as o}from"./chunks/framework.D4KxWb5R.js";const g=JSON.parse('{"title":"Teams","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/administration/teams.md","filePath":"src/en/guide/administration/teams.md"}'),n={name:"en/guide/administration/teams.md"};function i(s,e,m,d,l,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="teams" tabindex="-1">Teams <a class="header-anchor" href="#teams" aria-label="Permalink to &quot;Teams&quot;">​</a></h1><p>A team is a group of named accounts responsible for one or more products. <strong>Administration → Teams</strong> is for the CEO only.</p><h2 id="what-a-team-gives" tabindex="-1">What a team gives <a class="header-anchor" href="#what-a-team-gives" aria-label="Permalink to &quot;What a team gives&quot;">​</a></h2><p>Each member of a team responsible for a product, whatever their position:</p><ul><li>sees the product in their scope and in the intranet;</li><li>opens its back-office through SSO, without access granted account by account;</li><li>gets the alert when the product is desynchronized, or when its indicators can no longer be collected.</li></ul><p>An account can belong to several teams.</p><h2 id="creating-or-editing-a-team" tabindex="-1">Creating or editing a team <a class="header-anchor" href="#creating-or-editing-a-team" aria-label="Permalink to &quot;Creating or editing a team&quot;">​</a></h2><ol><li><strong>New team</strong> (or open an existing team).</li><li><strong>Name</strong> in English (required) and French, optional <strong>department</strong>.</li><li><strong>Members</strong>: search for accounts and add them.</li><li>Save.</li></ol><p>Members added or removed are notified. A team is not deleted.</p><h2 id="making-a-team-responsible-for-a-product" tabindex="-1">Making a team responsible for a product <a class="header-anchor" href="#making-a-team-responsible-for-a-product" aria-label="Permalink to &quot;Making a team responsible for a product&quot;">​</a></h2><p>Teams are chosen on the product page, in the <a href="./registry.html">registry</a>, under <strong>Responsible teams</strong>.</p><h2 id="removing-a-member-or-a-team" tabindex="-1">Removing a member or a team <a class="header-anchor" href="#removing-a-member-or-a-team" aria-label="Permalink to &quot;Removing a member or a team&quot;">​</a></h2><p>Removing a member from a team, or a team from a product, revokes the account&#39;s sessions and tokens for the back-offices it loses, unless it has access some other way (granted access or another team).</p><p>All these changes are recorded in the <a href="./logs.html">audit log</a>.</p>',14)])])}const p=a(n,[["render",i]]);export{g as __pageData,p as default};
